pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/**
 * @title DungeonCrawler
 * @dev A fully on-chain RPG. Characters are bound to addresses. Items are ERC1155 tokens.
 * Logic uses pseudorandomness suitable for low-stakes gameplay.
 */
contract DungeonCrawler is ERC1155, AccessControl, ReentrancyGuard {
    using Strings for uint256;

    // --- Roles ---
    bytes32 public constant GAME_MASTER_ROLE = keccak256("GAME_MASTER_ROLE");

    // --- Constants ---
    uint256 public constant COOLDOWN_PERIOD = 5 minutes;
    uint256 public constant MAX_STARTING_STATS = 10;

    // Item IDs
    uint256 public constant ID_POTION_HEALTH = 1;
    uint256 public constant ID_SCROLL_XP = 2;
    uint256 public constant ID_SWORD_BASIC = 10;
    uint256 public constant ID_BOW_BASIC = 11;
    uint256 public constant ID_WAND_BASIC = 12;
    uint256 public constant ID_ARTIFACT_BOSS = 99;

    // --- Structs ---
    struct Stats {
        uint8 strength;
        uint8 dexterity;
        uint8 intelligence;
    }

    struct Character {
        bool exists;
        uint16 level;
        uint32 xp;
        uint32 lastActionTimestamp;
        Stats stats;
        uint256 equippedWeapon; // Item ID, 0 if none
    }

    // --- State ---
    mapping(address => Character) public characters;
    mapping(uint256 => uint256) public itemPower; // ItemID => Stat Bonus

    // Events
    event CharacterCreated(address indexed player, uint8 str, uint8 dex, uint8 intl);
    event LevelUp(address indexed player, uint16 newLevel);
    event ExplorationResult(address indexed player, bool success, uint256 rewardId, uint32 xpGained);
    event ItemEquipped(address indexed player, uint256 itemId);

    // --- Constructor ---
    // Constraints: Empty, no parameters. Hardcode initial setup.
    constructor() ERC1155("https://api.dungeoncrawler.xyz/api/item/{id}.json") {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(GAME_MASTER_ROLE, msg.sender);

        // Define Item Power (Mock database of items)
        // Hardcoded in constructor as per deterministic requirements
        // We use a predefined mapping initialization pattern or simple checks in logic.
        // Due to "no params constructor" constraint, we can't pass arrays.
        // We will set them via admin functions or hardcode logic in resolution.
    }

    // --- Modifiers ---
    modifier hasCharacter() {
        require(characters[msg.sender].exists, "Character not created");
        _;
    }

    modifier cooldownCheck() {
        require(
            block.timestamp >= characters[msg.sender].lastActionTimestamp + COOLDOWN_PERIOD,
            "Action on cooldown"
        );
        _;
    }

    // --- Core Gameplay Functions ---

    /**
     * @dev Create a new character. Stat total must equal MAX_STARTING_STATS.
     */
    function createHero(uint8 str, uint8 dex, uint8 intl) external {
        require(!characters[msg.sender].exists, "Hero exists");
        require(str + dex + intl == MAX_STARTING_STATS, "Invalid stat allocation");
        require(str > 0 && dex > 0 && intl > 0, "Stats must be positive");

        characters[msg.sender] = Character({
            exists: true,
            level: 1,
            xp: 0,
            lastActionTimestamp: uint32(block.timestamp),
            stats: Stats(str, dex, intl),
            equippedWeapon: 0
        });

        // Give starter potion
        _mint(msg.sender, ID_POTION_HEALTH, 1, "");

        emit CharacterCreated(msg.sender, str, dex, intl);
    }

    /**
     * @dev Explore a dungeon tier. Resolution depends on stats vs difficulty.
     * @param difficultyTier 1 (Easy), 2 (Medium), 3 (Hard/Boss)
     */
    function explore(uint8 difficultyTier) external hasCharacter cooldownCheck nonReentrant {
        require(difficultyTier >= 1 && difficultyTier <= 3, "Invalid tier");
        Character storage char = characters[msg.sender];

        // Update cooldown
        char.lastActionTimestamp = uint32(block.timestamp);

        // Calculate Player Power
        uint256 power = _calculatePower(char);

        // Determine Difficulty (Linear scaling)
        uint256 difficulty = difficultyTier * 15 + (difficultyTier * 5); // 20, 40, 60

        // RNG Roll (Pseudo-random: Sufficient for low stakes RPG)
        // Includes msg.sender and counter to prevent simple replay within same block
        uint256 seed = uint256(keccak256(abi.encodePacked(
            block.timestamp, 
            block.prevrandao, 
            msg.sender, 
            char.xp
        )));

        uint256 roll = (seed % 100) + 1; // 1-100
        uint256 totalScore = roll + power;

        bool victory = totalScore >= difficulty;
        uint32 xpGain = 0;
        uint256 rewardItem = 0;

        if (victory) {
            // Success Logic
            xpGain = uint32(difficultyTier * 50);

            // Loot Chance: 20% base
            if ((seed % 10) < 2) { 
                rewardItem = _determineLoot(difficultyTier, seed);
                _mint(msg.sender, rewardItem, 1, "");
            }

            _addXp(msg.sender, xpGain);
        } else {
            // Failure Logic: Gain small pity XP
            xpGain = 5;
            _addXp(msg.sender, xpGain);
        }

        emit ExplorationResult(msg.sender, victory, rewardItem, xpGain);
    }

    /**
     * @dev Equip an item to boost stats. User must own the item.
     */
    function equipItem(uint256 itemId) external hasCharacter {
        require(balanceOf(msg.sender, itemId) > 0, "Item not owned");
        require(_isValidWeapon(itemId), "Not a weapon");

        characters[msg.sender].equippedWeapon = itemId;
        emit ItemEquipped(msg.sender, itemId);
    }

    /**
     * @dev Consume a potion to reset cooldown. Burns the token.
     */
    function drinkPotion() external hasCharacter {
        require(balanceOf(msg.sender, ID_POTION_HEALTH) > 0, "No potions");

        _burn(msg.sender, ID_POTION_HEALTH, 1);
        characters[msg.sender].lastActionTimestamp = 0; // Reset cooldown
    }

    // --- Internal Logic ---

    function _calculatePower(Character storage char) internal view returns (uint256) {
        uint256 base = char.stats.strength + char.stats.dexterity + char.stats.intelligence;
        uint256 bonus = 0;

        // Hardcoded item stats for simplicity and gas savings vs storage
        uint256 weapon = char.equippedWeapon;
        if (weapon == ID_SWORD_BASIC) bonus = 5;
        else if (weapon == ID_BOW_BASIC) bonus = 5;
        else if (weapon == ID_WAND_BASIC) bonus = 5;
        else if (weapon == ID_ARTIFACT_BOSS) bonus = 20;

        return base + bonus + (char.level * 2);
    }

    function _determineLoot(uint8 tier, uint256 seed) internal pure returns (uint256) {
        // Simple deterministic loot table
        uint256 selector = (seed >> 8) % 100;

        if (tier == 3) return ID_ARTIFACT_BOSS;

        if (selector < 33) return ID_SWORD_BASIC;
        if (selector < 66) return ID_BOW_BASIC;
        return ID_WAND_BASIC;
    }

    function _isValidWeapon(uint256 id) internal pure returns (bool) {
        return (id == ID_SWORD_BASIC || id == ID_BOW_BASIC || id == ID_WAND_BASIC || id == ID_ARTIFACT_BOSS);
    }

    function _addXp(address player, uint32 amount) internal {
        Character storage char = characters[player];
        char.xp += amount;

        // Level Up Formula: Level^2 * 100
        uint32 nextLevelXp = uint32(char.level) * uint32(char.level) * 100;

        if (char.xp >= nextLevelXp) {
            char.level++;
            // Stat boost on level up (Basic +1 all)
            char.stats.strength++;
            char.stats.dexterity++;
            char.stats.intelligence++;
            emit LevelUp(player, char.level);
        }
    }

    // --- Admin Functions ---

    function setURI(string memory newuri) external onlyRole(GAME_MASTER_ROLE) {
        _setURI(newuri);
    }

    function adminMint(address to, uint256 id, uint256 amount) external onlyRole(GAME_MASTER_ROLE) {
        _mint(to, id, amount, "");
    }

    // --- Overrides ---

    function supportsInterface(bytes4 interfaceId) public view override(ERC1155, AccessControl) returns (bool) {
        return super.supportsInterface(interfaceId);
    }

    /**
     * @dev Hook that is called before any token transfer. 
     * Used here to ensure equipped items cannot be transferred.
     */
    function _beforeTokenTransfer(
        address operator,
        address from,
        address to,
        uint256[] memory ids,
        uint256[] memory amounts,
        bytes memory data
    ) internal override {
        super._beforeTokenTransfer(operator, from, to, ids, amounts, data);

        // If transfer (not mint/burn), check if item is equipped
        if (from != address(0) && to != address(0)) {
            Character storage char = characters[from];
            if (char.exists && char.equippedWeapon != 0) {
                for (uint256 i = 0; i < ids.length; i++) {
                    require(ids[i] != char.equippedWeapon, "Cannot transfer equipped item");
                }
            }
        }
    }
}

